package com.intermarche.e2e.engine.stock;
import com.intermarche.backoffice.domain.store.*;
import io.quarkus.test.junit.*;
import io.quarkus.narayana.jta.QuarkusTransaction;
import jakarta.inject.Inject;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.*;
import org.mindrot.jbcrypt.BCrypt;
import java.util.*;
import java.nio.file.*;
import static io.restassured.RestAssured.given;
import static org.junit.jupiter.api.Assertions.*;

/** Actual HTTP+GraphQL serialization on a separate populated test database, never the demo database. */
@QuarkusTest @TestProfile(ProductStockHttpPerformanceTest.Isolated.class)
class ProductStockHttpPerformanceTest {
 public static class Isolated implements QuarkusTestProfile {public Map<String,String> getConfigOverrides(){return Map.of("quarkus.datasource.jdbc.url","jdbc:h2:mem:catalogue_http_benchmark;DB_CLOSE_DELAY=-1","quarkus.scheduler.enabled","false","imomswms.demo-data.enabled","false","imomswms.embeddings.enabled","false","quarkus.hibernate-orm.statistics","true","quarkus.log.category.\"io.smallrye.graphql\".level","WARN");}}
 @Inject EntityManager em;
 @Test void measurePagesAndSearchesWithFortyThousandStockedProducts()throws Exception {
  QuarkusTransaction.requiringNew().run(()->{
   Store s=new Store();s.code="HTTP40K";s.name="HTTP 40k";s.persist();StoreBuilding b=new StoreBuilding();b.buildingCode="HTTP40K-SHOP";b.persist();s.buildings.add(b);
   Employee e=new Employee();e.badgeId="HTTP40KM";e.firstName="Benchmark";e.lastName="Manager";e.email="bench@example.test";e.password=BCrypt.hashpw("bench-pin",BCrypt.gensalt(4));e.role=Employee.EmployeeRole.MANAGER;e.store=s;e.active=true;e.persist();em.flush();
   em.createNativeQuery("insert into products(id,version,created_at,updated_at,ean,name,productType,temperature_zone,is_active,characteristics) select next value for products_SEQ,0,current_timestamp,current_timestamp,'B40'||lpad(cast(x as varchar),10,'0'),'HTTP40K'||lpad(cast(x as varchar),5,'0'),'UNIT','AMBIENT',true,'Produit de performance avec stock renseigné' from system_range(1,40000)").executeUpdate();
   em.createNativeQuery("insert into item_locations(id,version,created_at,updated_at,type,building_id,product_id,area,aisle,unit,elevation,position,location_code) select next value for item_locations_SEQ,0,current_timestamp,current_timestamp,'SHELF',:building,p.id,'GROCERY','A1','B1','1','1','HTTP40K-'||p.id from products p where p.ean like 'B40%'").setParameter("building",b.id).executeUpdate();
   em.createNativeQuery("insert into stock_accounts(id,version,created_at,updated_at,store_id,product_id,safetyMargin,alertDirty) select next value for stock_accounts_SEQ,0,current_timestamp,current_timestamp,:store,p.id,0,false from products p where p.ean like 'B40%'").setParameter("store",s.id).executeUpdate();
   em.createNativeQuery("insert into stock_segments(id,version,created_at,updated_at,account_id,location_id,quality,segmentKey,receivedAt) select next value for stock_segments_SEQ,0,current_timestamp,current_timestamp,a.id,l.id,'UNASSESSED',cast(l.id as varchar),current_timestamp from stock_accounts a join item_locations l on l.product_id=a.product_id where a.store_id=:store").setParameter("store",s.id).executeUpdate();
   em.createNativeQuery("insert into stock_movements(id,version,created_at,updated_at,account_id,location_id,segment_id,quantity,effectiveAt,eventKey,reason) select next value for stock_movements_SEQ,0,current_timestamp,current_timestamp,a.id,l.id,sg.id,10,current_timestamp,'BENCH','INVENTORY' from stock_accounts a join item_locations l on l.product_id=a.product_id join stock_segments sg on sg.account_id=a.id and sg.location_id=l.id where a.store_id=:store").setParameter("store",s.id).executeUpdate();
  });
  String token=given().contentType("application/json").body(Map.of("username","HTTP40KM","password","bench-pin")).post("/auth/login").then().statusCode(200).extract().path("token");
  String query="query($search:String,$after:BigInteger,$limit:Int){stockPage(storeCode:\"HTTP40K\",search:$search,afterId:$after,limit:$limit){items{id productId stockKnown accountId product{ean name characteristics productType} physical availableToPromise safetyMargin balanceNow availabilityStatus placements{buildingId area aisle bay}} nextCursor hasMore scanned}}";
  var metrics=new LinkedHashMap<String,Object>();metrics.put("products",40000);metrics.put("stockAccounts",40000);metrics.put("stockMovements",40000);metrics.put("locations",40000);metrics.put("pageSize",30);metrics.put("environment","Local Quarkus test HTTP, H2 memory, one client; excludes browser rendering and network WAN");
  // Four fixed V8 bulk reads add segment identities, policies, quality holds and traced transit.
  // Cardinality invariance below remains the N+1 guard for 1 / 10 / 30 / 50 products.
  for(String search:List.of("HTTP40K","HTTP40K39999")){
   List<Long> times=new ArrayList<>();List<Long> loads=new ArrayList<>();List<Long> statements=new ArrayList<>();Long cursor=null;var statistics=em.getEntityManagerFactory().unwrap(org.hibernate.SessionFactory.class).getStatistics();
   for(int i=0;i<12;i++){var vars=new LinkedHashMap<String,Object>();vars.put("search",search);vars.put("after",cursor);vars.put("limit",30);long beforeSql=statistics.getPrepareStatementCount();long beforeLoads=statistics.getEntityLoadCount();long start=System.nanoTime();var result=given().auth().oauth2(token).contentType("application/json").body(Map.of("query",query,"variables",vars)).post("/graphql").then().statusCode(200).extract();times.add((System.nanoTime()-start)/1_000_000);loads.add(statistics.getEntityLoadCount()-beforeLoads);statements.add(statistics.getPrepareStatementCount()-beforeSql);assertTrue(statements.getLast()<=19,"SQL budget exceeded: "+statements.getLast());assertTrue(loads.getLast()<1000,"A page must not load the complete store topology: "+loads.getLast());assertNull(result.path("errors"),result.asString());assertEquals(search.equals("HTTP40K")?30:1,result.jsonPath().getList("data.stockPage.items").size());assertEquals(0,new java.math.BigDecimal("10").compareTo(new java.math.BigDecimal(result.jsonPath().getString("data.stockPage.items[0].physical"))));if(search.equals("HTTP40K"))cursor=result.jsonPath().getLong("data.stockPage.nextCursor");}
   var sorted=new ArrayList<>(times.subList(2,times.size()));Collections.sort(sorted);metrics.put(search.equals("HTTP40K")?"pages":"targetedSearch",Map.of("coldMs",times.getFirst(),"warmMedianMs",sorted.get(sorted.size()/2),"warmP95Ms",sorted.get((int)Math.ceil(sorted.size()*0.95)-1),"samplesMs",times,"entityLoads",loads,"sqlStatements",statements));
  }
  var scaling=new ArrayList<Map<String,Object>>();var stats=em.getEntityManagerFactory().unwrap(org.hibernate.SessionFactory.class).getStatistics();
  for(int size:List.of(1,10,30,50)) {
   long sql=stats.getPrepareStatementCount(),start=System.nanoTime();
   var response=given().auth().oauth2(token).contentType("application/json").body(Map.of("query",query,"variables",Map.of("search","HTTP40K","limit",size))).post("/graphql").then().statusCode(200).extract();
   assertNull(response.path("errors"),response.asString());assertEquals(size,response.jsonPath().getList("data.stockPage.items").size());
   scaling.add(Map.of("pageSize",size,"sqlStatements",stats.getPrepareStatementCount()-sql,"elapsedMs",(System.nanoTime()-start)/1_000_000));
  }
  metrics.put("queryScaling",scaling);
  assertEquals(1,scaling.stream().map(row->row.get("sqlStatements")).distinct().count(),"SQL count must not grow with the page size");
  QuarkusTransaction.requiringNew().run(()->{
   em.createNativeQuery("insert into stock_expected_supplies(id,version,created_at,updated_at,account_id,source_id,destination_id,reference,availableAt,quantity,received,picked,status) select next value for stock_expected_supplies_SEQ,0,current_timestamp,current_timestamp,a.id,l.id,l.id,'BENCH-TRANSFER',dateadd('hour',1,current_timestamp),2,0,2,'EXPECTED' from stock_accounts a join products p on p.id=a.product_id join item_locations l on l.product_id=p.id where p.name between 'HTTP40K00001' and 'HTTP40K00050'").executeUpdate();
   em.createNativeQuery("insert into stock_movements(id,version,created_at,updated_at,account_id,location_id,segment_id,quantity,effectiveAt,eventKey,reason) select next value for stock_movements_SEQ,0,current_timestamp,current_timestamp,x.account_id,x.source_id,sg.id,-2,current_timestamp,'BENCH-PICK','PICKING_'||x.id from stock_expected_supplies x join stock_segments sg on sg.account_id=x.account_id and sg.location_id=x.source_id where x.reference='BENCH-TRANSFER'").executeUpdate();
   em.createNativeQuery("insert into stock_commitments(id,version,created_at,updated_at,account_id,building_id,reference,preparationAt,quantity,remainingQuantity,status) select next value for stock_commitments_SEQ,0,current_timestamp,current_timestamp,a.id,l.building_id,'BENCH-COMMIT',dateadd('hour',2,current_timestamp),1,1,'ACTIVE' from stock_accounts a join products p on p.id=a.product_id join item_locations l on l.product_id=p.id where p.name between 'HTTP40K00001' and 'HTTP40K00050'").executeUpdate();
  });
  long richSql=stats.getPrepareStatementCount();
  var rich=given().auth().oauth2(token).contentType("application/json").body(Map.of("query",query,"variables",Map.of("search","HTTP40K","limit",50))).post("/graphql").then().statusCode(200).extract();
  long richCount=stats.getPrepareStatementCount()-richSql;
  assertNull(rich.path("errors"),rich.asString());assertEquals(50,rich.jsonPath().getList("data.stockPage.items").size());assertEquals(((Number)scaling.getLast().get("sqlStatements")).longValue(),richCount,"Transfers or commitments must use the same fixed bulk-query budget as an ordinary page");
  assertEquals(0,new java.math.BigDecimal("10").compareTo(new java.math.BigDecimal(rich.jsonPath().getString("data.stockPage.items[0].physical"))));
  metrics.put("withTransfersAndCommitments",Map.of("pageSize",50,"sqlStatements",richCount));
  measureActivity(token,metrics,stats);
  metrics.put("jpqlAttentionThresholdMs",100);
  metrics.put("jpqlOverThreshold",Arrays.stream(stats.getQueries()).filter(q->stats.getQueryStatistics(q).getExecutionMaxTime()>100).map(q->Map.of("query",q,"maxMs",stats.getQueryStatistics(q).getExecutionMaxTime(),"averageMs",stats.getQueryStatistics(q).getExecutionAvgTime(),"executions",stats.getQueryStatistics(q).getExecutionCount())).toList());
  // Inspect the paginated stock search itself: a cold JDBC slow-query warning must
  // remain reviewable even when Hibernate's HQL execution statistics stay below 100 ms.
  var searchPlan=QuarkusTransaction.requiringNew().call(()->{
   var scope=Store.findByCode("HTTP40K");String sql="select p.*,a.* from products p left join stock_accounts a on a.product_id=p.id and a.store_id=:store where p.is_active=true and p.id>0 and (lower(p.name) like :search escape '!' or p.ean like :ean escape '!') order by p.id fetch first 31 rows only";
   String plan=em.createNativeQuery("EXPLAIN "+sql,String.class).setParameter("store",scope.id).setParameter("search","%http40k%").setParameter("ean","http40k%").getSingleResult().toString();
   var samples=new ArrayList<Long>();for(int attempt=0;attempt<14;attempt++){long started=System.nanoTime();assertEquals(31,em.createNativeQuery(sql).setParameter("store",scope.id).setParameter("search","%http40k%").setParameter("ean","http40k%").getResultList().size());samples.add((System.nanoTime()-started)/1_000_000);}
   String orderedSql=sql.replace("order by p.id", "order by p.is_active,p.id");
   String orderedPlan=em.createNativeQuery("EXPLAIN ANALYZE "+orderedSql,String.class).setParameter("store",scope.id).setParameter("search","%http40k%").setParameter("ean","http40k%").getSingleResult().toString();
   assertTrue(orderedPlan.contains("index sorted"),"The active/id index must serve the page order without a whole-catalogue sort");
   var orderedSamples=new ArrayList<Long>();for(int attempt=0;attempt<14;attempt++){long started=System.nanoTime();assertEquals(31,em.createNativeQuery(orderedSql).setParameter("store",scope.id).setParameter("search","%http40k%").setParameter("ean","http40k%").getResultList().size());orderedSamples.add((System.nanoTime()-started)/1_000_000);}
   return Map.of("orderedPlan",orderedPlan,"orderedSamplesMs",orderedSamples,"plan",plan,"samplesMs",samples,"maxMs",Collections.max(samples),"rows",31,"catalogueProducts",40000,"review","Baseline id-only ordering compared with active/id index order. Production explicitly orders by active,id with active=true; the output order and cursor are identical, but the index now stops at 31 candidates. Sparse substring searches may still scan unmatched candidates. Fixed SQL count across page sizes asserted independently.");
  });metrics.put("stockSearchPlan",searchPlan);
  Files.writeString(Path.of("target/t10-http-performance.json"),new com.fasterxml.jackson.databind.ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(metrics));
  var volume=(Map<String,Object>)metrics.get("activityVolume");for(var m:((Map<String,Map<String,Object>>)volume.get("measurements")).values())assertTrue(((Number)m.get("p95Ms")).longValue()<=150,"Warm mission/activity P95 target 150 ms exceeded; complete report saved: "+m.get("p95Ms"));
 }
 void measureActivity(String token,Map<String,Object> metrics,org.hibernate.stat.Statistics stats)throws Exception{
  Long[] scope=QuarkusTransaction.requiringNew().call(()->{var store=Store.findByCode("HTTP40K");var employee=Employee.findByBadgeId("HTTP40KM");
   em.createNativeQuery("insert into handling_orders(id,version,created_at,updated_at,type,store_id,assignee_id,status,code,requested_start,requested_end) select next value for handling_orders_SEQ,0,current_timestamp,current_timestamp,'PRODUCT_COLLECTING',:store,case when mod(x,2)=0 then :employee else null end,case when mod(x,10)=0 then 'DONE' else 'SCHEDULED' end,'BM-'||lpad(cast(x as varchar),6,'0'),current_timestamp,dateadd('hour',1,current_timestamp) from system_range(1,5000)").setParameter("store",store.id).setParameter("employee",employee.id).executeUpdate();
   em.createNativeQuery("insert into mission_preparation_contexts(id,version,created_at,updated_at,store_id,handlingOrder_id,mode,groupCode) select next value for mission_preparation_contexts_SEQ,0,current_timestamp,current_timestamp,:store,o.id,'WAVE','BENCH-WAVE' from handling_orders o where o.store_id=:store").setParameter("store",store.id).executeUpdate();
   em.createNativeQuery("insert into handling_executions(id,version,created_at,updated_at,execution_type,handling_order_id,employee_id,execution_status) select next value for handling_executions_SEQ,0,current_timestamp,current_timestamp,'PICKING',o.id,:employee,'IN_PROGRESS' from handling_orders o where o.store_id=:store and o.assignee_id=:employee and o.status='SCHEDULED'").setParameter("employee",employee.id).setParameter("store",store.id).executeUpdate();
   em.createNativeQuery("insert into stock_operation_receipts(id,version,created_at,updated_at,store_id,actor,requestKey,fingerprint,operation,result) select next value for stock_operation_receipts_SEQ,0,current_timestamp,current_timestamp,:store,'HTTP40KM','BENCH-RECEIPT-'||x,'PERFORMANCE_FIXTURE','BENCHMARK','{}' from system_range(1,5000)").setParameter("store",store.id).executeUpdate();
   em.createNativeQuery("insert into activity_quantities(id,version,created_at,updated_at,store_id,actor,source,receipt_id,ordinal,action,metric,unit,quantity,productId,lineId) select next value for activity_quantities_SEQ,0,current_timestamp,current_timestamp,:store,'HTTP40KM','OPERATION',r.id,0,case when mod(r.id,100)<50 then 'PACKING_REPORT' else 'GROUPING_REPORT' end,case when mod(r.id,100)<50 then 'PACKED' else 'GROUPED' end,'PCS',2,null,r.id from stock_operation_receipts r where r.store_id=:store").setParameter("store",store.id).executeUpdate();
   em.createNativeQuery("update stock_movements set activity_actor='HTTP40KM',activity_unit='PCS' where account_id in (select id from stock_accounts where store_id=:store)").setParameter("store",store.id).executeUpdate();
   return new Long[]{store.id,employee.id};});
  var reports=new LinkedHashMap<String,Object>();
  for(String route:List.of("/handling-orders/operator/orders/page?storeId="+scope[0]+"&limit=30&state=ACTIVE&assignment=MINE","/handling-orders/operator/consultation/activity?storeId="+scope[0]+"&limit=30")){
   var times=new ArrayList<Long>();var sql=new ArrayList<Long>();var loads=new ArrayList<Long>();var bytes=new ArrayList<Integer>();
   for(int n=0;n<14;n++){long q=stats.getPrepareStatementCount(),entities=stats.getEntityLoadCount(),start=System.nanoTime();var response=given().auth().oauth2(token).get(route).then().statusCode(200).extract();times.add((System.nanoTime()-start)/1_000_000);sql.add(stats.getPrepareStatementCount()-q);loads.add(stats.getEntityLoadCount()-entities);bytes.add(response.asByteArray().length);assertEquals(30,response.jsonPath().getList("items").size());assertTrue(response.asByteArray().length<100_000);if(route.contains("/orders/"))assertEquals("WAVE",response.jsonPath().getString("items[0].preparation.mode"));assertTrue(loads.getLast()<20,"Mission cards must not load full order graphs");assertEquals(8,sql.getLast(),"Mission/activity request query count must remain fixed (6 + the 2 lookups of the account behind the token)");}
   var warm=new ArrayList<>(times.subList(2,times.size()));Collections.sort(warm);long p50=warm.get(warm.size()/2),p95=warm.get((int)Math.ceil(warm.size()*.95)-1);
   reports.put(route.contains("/orders/")?"missions":"ownActivity",Map.of("coldMs",times.getFirst(),"p50Ms",p50,"p95Ms",p95,"serialThroughputRequestsPerSecond",12000d/warm.stream().mapToLong(Long::longValue).sum(),"sqlStatements",sql,"entityLoads",loads,"responseBytes",bytes,"samplesMs",times));
  }
  var summaryTimes=new ArrayList<Long>();var summarySql=new ArrayList<Long>();var summaryLoads=new ArrayList<Long>();
  for(int n=0;n<14;n++){long q=stats.getPrepareStatementCount(),loaded=stats.getEntityLoadCount(),start=System.nanoTime();var response=given().auth().oauth2(token).get("/handling-orders/operator/consultation/summary?storeId="+scope[0]).then().statusCode(200).extract();summaryTimes.add((System.nanoTime()-start)/1_000_000);summarySql.add(stats.getPrepareStatementCount()-q);summaryLoads.add(stats.getEntityLoadCount()-loaded);assertEquals("ALL_CONFIRMED_OPERATIONS",response.jsonPath().getString("basis"));assertEquals(2,response.jsonPath().getList("operations").size());assertEquals(2,response.jsonPath().getList("physicalQuantities").size());var physicalRows=response.jsonPath().<Map<String,Object>>getList("physicalQuantities");var inventory=physicalRows.stream().filter(v->"INVENTORY".equals(v.get("operation"))).findFirst().orElseThrow();assertEquals(0,new java.math.BigDecimal("400000").compareTo(new java.math.BigDecimal(inventory.get("incoming").toString())));var replenishment=physicalRows.stream().filter(v->"REPLENISHMENT_PICK".equals(v.get("operation"))).findFirst().orElseThrow();assertEquals(0,new java.math.BigDecimal("100").compareTo(new java.math.BigDecimal(replenishment.get("outgoing").toString())));}
  var summaryWarm=new ArrayList<>(summaryTimes.subList(2,summaryTimes.size()));Collections.sort(summaryWarm);long summaryP95=summaryWarm.get((int)Math.ceil(summaryWarm.size()*.95)-1);assertEquals(1,summarySql.stream().distinct().count());assertTrue(summaryLoads.stream().allMatch(n->n<20),"The summary must aggregate scalars, not load receipt LOBs or product graphs");reports.put("allOperationQuantities",Map.of("coldMs",summaryTimes.getFirst(),"p50Ms",summaryWarm.get(summaryWarm.size()/2),"p95Ms",summaryP95,"sqlStatements",summarySql,"entityLoads",summaryLoads,"quantityFacts",5000,"physicalMovements",40050,"samplesMs",summaryTimes));
  var scaling=new ArrayList<Map<String,Object>>();
  for(int size:List.of(1,10,30,100)){long sql=stats.getPrepareStatementCount(),loaded=stats.getEntityLoadCount();var response=given().auth().oauth2(token).get("/handling-orders/operator/orders/page?storeId="+scope[0]+"&limit="+size+"&state=ACTIVE&assignment=ALL").then().statusCode(200).extract();assertEquals(size,response.jsonPath().getList("items").size());scaling.add(Map.of("size",size,"sql",stats.getPrepareStatementCount()-sql,"entityLoads",stats.getEntityLoadCount()-loaded,"bytes",response.asByteArray().length));}
  assertEquals(1,scaling.stream().map(r->r.get("sql")).distinct().count(),"Mission summary query count must not grow with page size");
  Set<Long> seen=new HashSet<>();long cursor=0;int pages=0;boolean more;
  do{var response=given().auth().oauth2(token).get("/handling-orders/operator/orders/page?storeId="+scope[0]+"&limit=100&state=ALL&assignment=ALL&before="+cursor).then().statusCode(200).extract();for(Number id:response.jsonPath().<Number>getList("items.id"))assertTrue(seen.add(id.longValue()),"Duplicate mission across pages");more=response.jsonPath().getBoolean("hasMore");long next=response.jsonPath().getLong("nextBefore");assertTrue(next<cursor||cursor==0);cursor=next;pages++;}while(more);
  assertEquals(5000,seen.size());assertEquals(50,pages);
  var runtime=Runtime.getRuntime();metrics.put("environmentDetails",Map.of("java",Runtime.version().toString(),"os",System.getProperty("os.name"),"architecture",System.getProperty("os.arch"),"processors",runtime.availableProcessors(),"memoryMethod","JVM heap usage snapshot after benchmark; not a production capacity estimate"));metrics.put("activityVolume",Map.of("missions",5000,"executions",2000,"receipts",5000,"measurements",reports,"queryScaling",scaling,"continuousPages",pages,"distinctMissionIds",seen.size(),"heapUsedBytes",runtime.totalMemory()-runtime.freeMemory(),"heapMaxBytes",runtime.maxMemory(),"targetWarmP95Ms",150));
 }

}
